WITH valid AS (SELECT *, CONCAT_WS(',', dept_name, location) AS dept_name_location_key, COALESCE(dept_name, 'NONE') AS dept_name_clean FROM departments WHERE location IS NOT NULL AND location IS DISTINCT FROM 'New York') SELECT CASE WHEN budget >= 3823000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, COUNT_IF(location = 'Tokyo') AS tokyo_events, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, COUNT(DISTINCT dept_name) AS distinct_dept_names FROM valid GROUP BY CASE WHEN budget >= 3823000 THEN 'HIGH' ELSE 'LOW' END HAVING distinct_dept_names > 1;
